\label{MainThm}
Assume that
\begin{enumerate}[label=(\Alph*), ref={\Alph*}]
    \item \label{case:neq} $a_i b_j \ne  a_j b_i$ whenever $i \ne j$, \textbf{or}
    \item \label{case:eq} $\mathbf a = \mathbf b$, and $\mathcal V'$ has a non-singular point over $\mathbb R$ and over $\mathbb Q_p$ for each prime $p$.
\end{enumerate}
Let ${\delta} > 0$, and let $\mathcal A \subseteq [N]$ with $\# \mathcal A \geqslant {\delta} N$. Then
\[
\# \mathcal A^s \cap \mathcal V \gg_{\mathcal V, {\delta}} N^{s-k-1}.
\]

\label{WR}
Let $\Phi$ be a closed subset of $\mathbb T^N$ containing zero, and let ${\varepsilon} > 0$. Let $f: [N] \to \mathbb C$ be $1$-bounded, meaning that $|f| \leqslant 1$ pointwise. Then there exists $d \leqslant (4/{\varepsilon})^2$ and $\phi \in \Phi^d$ such that
\begin{equation}
\label{WRerror}
\| f - f_\phi \|_\Phi \leqslant {\varepsilon} N.
\end{equation}

\label{RWR}
Let $\Phi$ be a closed subset of $\mathbb T^N$, and let $\phi \in \Phi^d$. Let ${\varepsilon} > 0$, and let $f: \mathbb N \to \mathbb C$ be a $1$-bounded function. Then there exist $d' \leqslant (4/{\varepsilon})^2$ and $\phi' \in \Phi^{d'}$ such that
\begin{equation}
\label{RWRbound}
\| f- f_{\phi, \phi'} \|_\Phi \leqslant {\varepsilon} N.
\end{equation}

We carry out the energy increment process used to prove Lemma \ref{WR}, initialising with $f_\phi$ instead of $f_0$. At each stage, we query whether or not \eqref{RWRbound} holds. If not, then we increase the quantity
\begin{equation}
\label{incrementor}
\int_{\mathbb T^{d+d'}} \| f_{\phi, \phi'}^{{\boldsymbol{{\alpha}}}, {\boldsymbol{{\alpha}}}'} \|_2^2 \mathrm{d} {\boldsymbol{{\alpha}}} \mathrm{d} {\boldsymbol{{\alpha}}}'
\end{equation}
by $({\varepsilon}/4)^2 N$. Since \eqref{incrementor} is bounded above by $N$, this procedure must terminate within $d' \leqslant (4/{\varepsilon})^2$ many steps.

\label{SymDif}
Let $0 < {\varepsilon} \leqslant 1/2$ and ${\boldsymbol{{\gamma}}} \in \mathbb T^d$. Then
\[
\operatorname{meas}_{\mathbb T^d}
([0,{\varepsilon})^d {\Delta} ([0,{\varepsilon})^d + {\boldsymbol{{\gamma}}})) \leqslant 2 {\varepsilon}^{d-1} \sum_{j \in [d]} \| {\gamma}_j \|_\mathbb T.
\]

\label{lm:fi-minor-arc-bound}
If $i\in[s]$ and $(\alpha, \beta)\in\mathfrak m$ then
\begin{equation}
f_i(\alpha, \beta) \ll N^{1+ \varepsilon - \Delta/k}.
\end{equation}

Observe that
    \begin{equation*}
        f_i(\alpha, \beta)
        = \sum_{L<mx + u\leqslant R}e(a_i\alpha(mx+u)^{k} + b_i\beta (mx + u))
        = \sum_{\frac{L-u}{m} < x \leqslant \frac{R-u}{m}} e(h_i(x)),
    \end{equation*}
    for the polynomial $h_i$ given by
    \begin{equation}
        \label{eq:hi-def}
        h_i(x) = h_i(x; \alpha, \beta) = \eta_{i, k} x^{k} +\dots+ \eta_{i, 1} x + \eta_{i, 0},
    \end{equation}
    where
    \begin{equation}
        \label{eq:hi-coefficients}
        \begin{gathered}
            \eta_{i, j} = a_i\alpha m^{j}u^{k-j} \binom k j\qquad (2\leqslant j \leqslant k),
            \\
            \eta_{i, 1} = a_i\alpha m u^{k-1}k + b_i\beta m,
            \qquad
            \eta _{i, 0} = a_i\alpha u^{k} + b_i\beta u.
        \end{gathered}
    \end{equation} 

    Suppose
    \begin{equation}
        \abs{f_i(\alpha, \beta)} > 2N^{1+\varepsilon - \Delta/k}.
    \end{equation}
    Then for some $X\in\{(L-u)/m, (R-u)/m\}$, we have
    \begin{equation}
    \abs[\Big]{\sum_{x\leqslant X} e(h_i(x; \alpha, \beta))} > N^{1+ \varepsilon - \Delta/k}.
    \end{equation}
    Now, by \cite[Theorem 5.1]{Bak1986} applied with $M=1$ and $P=N^{1+ \varepsilon - \Delta/k}$, there exist $r\in\mathbb N$ and $\boldsymbol{\mathbf{u}}\in\mathbb Z ^{k}$ for which 
    \begin{equation}
        r < N^{\Delta}/\log N,\qquad \gcd(r, u_k, \dots, u_1) = 1,
    \end{equation}
    and
    \begin{equation}
        \abs{r\eta_{i, j} - u_j} < \frac{N^{\Delta -j}}{\log N}
        \qquad (1\leqslant j \leqslant s).
    \end{equation}
    By the triangle inequality, we have
    \begin{equation}
        \abs{rb_im^{k}\beta - (u_1m^{k-1}-ku_ku^{k-1})} < \frac{2m^{k-1}N^{\Delta -1}}{\log N}.
    \end{equation}
    Set
    \begin{equation}
        q' = ra_ib_im^{k}, \qquad a' = b_i u _k, \qquad b'=a_i(u_1m^{k-1}-ku_2u^{k-1}).
    \end{equation}
    Then \eqref{eq:major-arc-def} and \eqref{eq:major-arc-range} are satisfied by
    \begin{equation}
        q = \frac{q'}{\gcd(q', a', b')},\qquad a = \frac{a'}{\gcd(q', a', b')}, \qquad b = \frac{b'}{\gcd(q', a', b')},
    \end{equation}
    so $(\alpha, \beta) \in \mathfrak M$.

\label{lm:moment-bound}
For $i \in [s]$,
\begin{equation}
\int_{\mathbb T^{2}}
\abs{ f_i(\alpha, \beta)}^{s_0 -1} \mathrm{d} \alpha \mathrm{d} \beta \ll N^{s_0 - k - 2 + \varepsilon}.
\end{equation}

Define
    \begin{equation}
        f'(\alpha, \beta) = \sum_{n\leqslant N}e(\alpha n^{k} + \beta n).
    \end{equation}
    For each natural number $t$, by orthogonality we may interpret
    \begin{equation}
        \int_{\mathbb T^{2}}\abs{f(\alpha, \beta)}^{2t} \mathrm{d} \alpha \mathrm{d} \beta
        \qquad \text{and} \qquad
        \int_{\mathbb T^{2}}\abs{ f'(\alpha, \beta)}^{2t} \mathrm{d} \alpha \mathrm{d} \beta
    \end{equation}
    as counts of solutions to
    \begin{align}
        x_1^{k} + \dots + x_{t}^{k} &= 
        y_1^{k} + \dots + y_{t}^{k},
        \\
        x_1 + \dots + x_{t} &= 
        y_1 + \dots + y_{t},
    \end{align}
    in $\mathcal P^{2t}$ and in $[N]^{2t}$, respectively.
    Noting that $s_0$ is an odd integer, it follows that
    \begin{equation}
        \label{eq:no-progression-moment-is-larger}
        \int_{\mathbb T^{2}}\abs{f_i(\alpha, \beta)}^{s_0 -1} \mathrm{d} \alpha \mathrm{d} \beta
        = \int_{\mathbb T^{2}}\abs{f(\alpha, \beta)}^{s_0 -1} \mathrm{d} \alpha \mathrm{d} \beta \leqslant 
        \int_{\mathbb T^{2}}\abs{f'(\alpha, \beta)}^{s_0 -1} \mathrm{d} \alpha \mathrm{d} \beta,
    \end{equation}
    so it suffices to prove the bound with $f'$ in place of $f_i$.

    The case $k=2$ is a classical result, see for instance Rogovskaya \cite{Rog1986}.
    When $3\leqslant k \leqslant 6$ the result follows from the discussion after \cite[Equation (14.26)]{Woo2019}.
    Finally, when $k\geqslant 7$, put
    \begin{equation}
        r = 1 + k - \lfloor \sqrt{2k+2} \rfloor,
        \qquad
        v = k(k+1) - \frac{k(k+1)- r(r+1)}{1 + k -r}.
    \end{equation}
    Then we have
    \begin{align}
        v
        &= k^{2}-r -2 + \frac{2k + 2}{1+k-r} 
        \\
        &= k(k-1) + \lfloor \sqrt{2k+2} \rfloor - 3 + \frac{2k + 2}{\lfloor \sqrt{2k+2} \rfloor}
        \\
        &= k(k-1) + 2\lfloor \sqrt{2k+2} \rfloor - 3 + \frac{2k + 2 - \lfloor \sqrt{2k+2} \rfloor^{2}}{\lfloor \sqrt{2k+2} \rfloor},
    \end{align}
    and since
    \begin{equation}
        \frac{2k + 2 - \lfloor \sqrt{2k+2} \rfloor^{2}}{\lfloor \sqrt{2k+2} \rfloor} \in [0, 2],
    \end{equation}
    it is clear that $v \geqslant k(k-1) + 2$. An application of \cite[Theorem 14.5]{Woo2019} now yields
    \begin{equation}
        \int_{\mathbb T^{2}}\abs{f'(\alpha, \beta)}^{v} \mathrm{d} \alpha \mathrm{d} \beta \ll N^{v-k-1 + \varepsilon}.
    \end{equation}
    It follows from \eqref{eq:s_0-large-k-def} and \eqref{eq:theta-k-def} that $v \leqslant s_0 -1$, concluding the proof of the lemma.

\label{lm:S-from-sol-count}
    For $q\in\mathbb N$, 
    \begin{equation}
        \sum_{d\mid q}S(d) = q^{2-s}M(q).
    \end{equation}

By orthogonality, 
\begin{align*}
&M(q)
= q^{-2}\sum_{v, w\leqslant q} \ \sum_{x_1,\dots,x_s \leqslant q}e_q(v\mathfrak F(m\boldsymbol{\mathbf{x}} + \boldsymbol{\mathbf{u}}) + w\mathfrak L(m\boldsymbol{\mathbf{x}} + \boldsymbol{\mathbf{u}}))
\\
&= q^{-2} \sum_{d \mid q} \sum_{\substack{a,b \leqslant d \\ \gcd(d, a, b)=1}}
(q/d)^{s} \sum_{x_1,\dots,x_s \leqslant d} e_d(a\mathfrak F(m\boldsymbol{\mathbf{x}} + \boldsymbol{\mathbf{u}}) + b\mathfrak L(m\boldsymbol{\mathbf{x}} + \boldsymbol{\mathbf{u}}))
\\
&= q^{s-2}\sum_{d\mid q}S(d).
\end{align*}

If $p$ is prime then
    \begin{equation}
        \chi_p = \lim_{t\to \infty}p^{-t(s-2)}M(p^{t}).
    \end{equation}

\label{lm:sol-count-from-Sstar}
    For $Q\in\mathbb N$, 
    \begin{equation}
        \sum_{d,d'\mid Q}S^{*}(d,d') = Q^{5-2s}M^{*}(Q).
    \end{equation}

By orthogonality, 
\begin{align}
M^{*}(Q)
&=
\begin{multlined}[t]
Q^{-4} \sum_{v,w,v',w' \leqslant Q} \ \sum_{x_1,\dots,x_s,x'_2,\dots,x_s'\leqslant Q}
e_Q(v\mathfrak F(m\boldsymbol{\mathbf{x}} + \boldsymbol{\mathbf{u}}) + w\mathfrak L(m\boldsymbol{\mathbf{x}} + \boldsymbol{\mathbf{u}}))
\\
\cdot e_Q(v'\mathfrak F(m\boldsymbol{\mathbf{x}}' + \boldsymbol{\mathbf{u}}) + w'\mathfrak L(m\boldsymbol{\mathbf{x}}' + \boldsymbol{\mathbf{u}}))
\end{multlined}
\\
&=
Q^{-5} \sum_{d, d'\mid Q}(Q/d)^{s}(Q/d')^{s}
\sum_{\substack{a,b \leqslant d, \, \gcd(d,a, b) = 1
\\
a',b' \leqslant d',\, \gcd(d',a', b') = 1
}} \
\sum_{\substack{
x_1 \leqslant dd' \\
x_2, \dots, x_s \leqslant d \\
x_2', \dots, x'_s \leqslant d'}}
\\
&\qquad\qquad e_d(a\mathfrak F(m\boldsymbol{\mathbf{x}} + \boldsymbol{\mathbf{u}}) + b\mathfrak L(m\boldsymbol{\mathbf{x}} + \boldsymbol{\mathbf{u}})) e_{d'}(a'\mathfrak F(m\boldsymbol{\mathbf{x}}' + \boldsymbol{\mathbf{u}}) + b'\mathfrak L(m\boldsymbol{\mathbf{x}}' + \boldsymbol{\mathbf{u}}))
\\
&= Q^{2s-5} \sum_{d, d' \mid Q}
S^{*}(d, d').
\end{align}

\label{cor:chistar-as-limit}
    If $p$ is prime, then
    \begin{equation}
        \chi^{*}_{p} = \lim_{t\to \infty}p^{-t(2s-5)}M^{*}(p^{t}).
    \end{equation}

\label{l2}
If $g_1, \ldots, g_s: \mathcal P \to \mathbb C$ are $1$-bounded, and $N \geqslant N_0(M)$, then
\[
T(\mathbf g) \ll T(1_\mathcal P) \frac{\| g_i \|_2}{\|1_\mathcal P\|_2}
\qquad (1 \leqslant i \leqslant s).
\]

\label{ConstrainedOrth}
Let $a_1, \ldots, a_s \in \mathbb Z$ be integers such that $\gcd(a_1, \ldots, a_s) = 1$, and let $\mathbf m^{(1)}, \ldots, \mathbf m^{(s)} \in \mathbb Z^d$. Then
\[
\int_{\mathcal K(\mathbf a, d)}
e \Bigl(
\sum_{i \in [s]}
\mathbf m^{(i)} \cdot {\boldsymbol{{\gamma}}}^{(i)} \Bigr) \mathrm{d} {\boldsymbol{{\gamma}}} =
\begin{cases}
1, &\text{if } a_i \mathbf m^{(j)} = a_j \mathbf m^{(i)} \text{ for all } i, j \\
0, &\text{otherwise}.
\end{cases}
\]

First suppose $a_i \mathbf m^{(j)} = a_j \mathbf m^{(i)}$ for all $i,j$. Then, by Lemma \ref{parallel}, there exists $\mathbf m \in \mathbb Z^d$ such that $\mathbf m^{(i)} = a_i \mathbf m$ for all $i$. Consequently,
\[
\int_{\mathcal K(\mathbf a,d)}
e \Bigl( \sum_{i \in [s]} \mathbf m^{(i)} \cdot {\boldsymbol{{\gamma}}}^{(i)} \Bigr) \mathrm{d} {\boldsymbol{{\gamma}}}
= \int_{\mathcal K(\mathbf a,d)}
e \Bigl( \mathbf m \cdot \sum_{i \in [s]} a_i {\boldsymbol{{\gamma}}}^{(i)} \Bigr) \mathrm{d} {\boldsymbol{{\gamma}}} = 1.
\]

Now suppose instead that there exist $i,j$ with $a_i \mathbf m^{(j)} \ne a_j \mathbf m^{(i)}$. We claim that there exists $\tilde {\boldsymbol{{\gamma}}} \in \mathcal K(\mathbf a, d)$ such that $\sum_{i \in [s]} \mathbf m^{(i)} \cdot \tilde {\boldsymbol{{\gamma}}}^{(i)} \ne \mathbf 0 \in \mathbb T^d$. Assuming that such a vector $\tilde {\boldsymbol{{\gamma}}}$ exists, translation-invariance of $\mathcal K(\mathbf a, d)$ and a change of variables give
\begin{align}
    &e \Bigl( \sum_{i \in [s]} \mathbf m^{(i)} \cdot \tilde {\boldsymbol{{\gamma}}}^{(i)} \Bigr) \int_{\mathcal K(\mathbf a,d)}
    e \Bigl( \sum_{i \in [s]} \mathbf m^{(i)} \cdot {\boldsymbol{{\gamma}}}^{(i)} \Bigr) \mathrm{d} {\boldsymbol{{\gamma}}} \\
    &= \int_{\mathcal K(\mathbf a,d)}
    e \Bigl( \sum_{i \in [s]} \mathbf m^{(i)} \cdot ({\boldsymbol{{\gamma}}}^{(i)} + \tilde {\boldsymbol{{\gamma}}}^{(i)}) \Bigr) \mathrm{d} {\boldsymbol{{\gamma}}}
    = \int_{\mathcal K(\mathbf a,d)}
    e \Bigl( \sum_{i \in [s]} \mathbf m^{(i)} \cdot {\boldsymbol{{\gamma}}}^{(i)} \Bigr) \mathrm{d} {\boldsymbol{{\gamma}}},
\end{align}
whereupon $\int_{\mathcal K(\mathbf a,d)}
e \bigl( \sum_{i \in [s]} \mathbf m^{(i)} \cdot {\boldsymbol{{\gamma}}}^{(i)} \bigr) \mathrm{d} {\boldsymbol{{\gamma}}} = 0$.

It remains to establish the claim. Fixing $i$ and $j$ such that $a_i \mathbf m^{(j)} \ne a_j \mathbf m^{(i)}$, let $k \in [d]$ be such that $a_i m_{j,k} \ne a_j m_{i,k}$. Choosing $\tilde {\gamma}_{\ell, m} = 0$ if $\ell \notin \{ i, j \}$ or $m \ne k$, it now suffices to find $\tilde {\gamma}_{i,k}$ and $\tilde {\gamma}_{j,k}$ such that
\begin{align*}
a_i \tilde {\gamma}_{i,k} + a_j \tilde {\gamma}_{j,k} &= 0 \in \mathbb T, \\
m_{i,k} \tilde {\gamma}_{i,k} + m_{j,k} \tilde {\gamma}_{j,k} &\ne 0 \in \mathbb T,
\end{align*}
since the first condition ensures that $\tilde {\boldsymbol{{\gamma}}} \in \mathcal K(\mathbf a, d)$ and the second condition ensures that $\sum_{\ell \in [s]} \mathbf m^{(\ell)} \cdot \tilde {\boldsymbol{{\gamma}}}^{(\ell)} \ne \mathbf 0 \in \mathbb T^d$. As
\[
\begin{pmatrix}
a_i & a_j \\
m_{i,k} & m_{j,k}
\end{pmatrix}
\]
is an invertible real matrix, there exist ${\alpha}, {\beta} \in \mathbb R$ such that
\[
a_i {\alpha} + a_j {\beta} = 0, \qquad
m_{i,k} {\alpha} + m_{j,k} {\beta} = 1/2.
\]
Choosing $\tilde {\gamma}_{i,k} = {\alpha} \: \mathrm{mod} \: 1$ and $\tilde {\gamma}_{j,k} = {\beta} \: \mathrm{mod} \: 1$ delivers the claim.

\label{equi2}
Let $a_1, \ldots, a_s, b_1, \ldots, b_s \in \mathbb Z$ be such that
$$
\gcd(a_1, \ldots, a_s) = \gcd(b_1, \ldots, b_s) = 1.
$$
Let $A \geqslant CM$, where $C = 2 \| (\mathbf a, \mathbf b) \|_\infty$.
Let $d = d_1 + d_k \leqslant M$, and let $F: \mathbb T^d \to \mathbb C$ be a $1$-bounded trigonometric polynomial of degree at most $M$. If               
each ${\boldsymbol{\theta}}^{(i)} \in \mathbb T^{d_i}$ is $(A,N^i)$-irrational, then
\begin{align}
&\sum_{\mathbf n \in \mathcal V(\mathcal P)} F({\boldsymbol{\theta}}^{(1)} n_1, {\boldsymbol{\theta}}^{(k)} n_1^k) \cdots F({\boldsymbol{\theta}}^{(1)} n_s, {\boldsymbol{\theta}}^{(k)} n_s^k) \\
&= T(1_\mathcal P) \int_{\mathcal K(\mathbf a, d_k)} \int_{\mathcal K(\mathbf b, d_1)} \prod_{i \leqslant s} F({\boldsymbol{{\gamma}}}^{(i)}, \tilde {\boldsymbol{{\gamma}}}^{(i)}) \mathrm{d} {\boldsymbol{{\gamma}}} \mathrm{d}  \tilde {\boldsymbol{{\gamma}}}
+O(M^{O(1)} A^{-{\Omega}(1)} N^{s-k-1}).
\end{align}
